      first_touch TEXT, last_touch TEXT,
      anon_id TEXT,
      ip TEXT, country TEXT, city TEXT, user_agent TEXT, device TEXT,
      tz TEXT, lang TEXT,
      first_seen_at TEXT, form_ms INTEGER,
      backfilled INTEGER NOT NULL DEFAULT 0,
      created_at TEXT NOT NULL DEFAULT (datetime('now'))
    );
;;
CREATE TABLE IF NOT EXISTS analytics_events (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      user_id INTEGER,
      anon_id TEXT,
      event TEXT NOT NULL,
      props TEXT,
      path TEXT,
      ip TEXT,
      created_at TEXT NOT NULL DEFAULT (datetime('now'))
    );
;;
CREATE TABLE IF NOT EXISTS lifecycle_emails (
      user_id INTEGER NOT NULL,
      kind TEXT NOT NULL,
      sent_at TEXT NOT NULL DEFAULT (datetime('now')),
      PRIMARY KEY (user_id, kind)
    );
;;
CREATE TABLE IF NOT EXISTS user_milestones (
      user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
      key TEXT NOT NULL,
      props TEXT,
      at TEXT NOT NULL DEFAULT (datetime('now')),
      PRIMARY KEY (user_id, key)
    );
;;
CREATE TABLE IF NOT EXISTS push_subscriptions (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
      endpoint TEXT NOT NULL UNIQUE,
      p256dh TEXT NOT NULL,
      auth TEXT NOT NULL,
      user_agent TEXT,
      created_at TEXT NOT NULL DEFAULT (datetime('now')),
      last_ok_at TEXT,
      fail_count INTEGER NOT NULL DEFAULT 0
    );
;;
CREATE TABLE IF NOT EXISTS app_auth_handoff (
        nonce_hash TEXT PRIMARY KEY,
        token TEXT,
        error TEXT,
        expires_at INTEGER NOT NULL,
        created_at DATETIME DEFAULT CURRENT_TIMESTAMP
      );
;;
CREATE TABLE IF NOT EXISTS invoice_profiles (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
        name TEXT NOT NULL,
        layout TEXT NOT NULL DEFAULT 'classic',
        currency TEXT NOT NULL DEFAULT 'USD',
        number_format TEXT NOT NULL DEFAULT '{SEQ}',
        next_seq INTEGER NOT NULL DEFAULT 1,
        due_days INTEGER NOT NULL DEFAULT 14,
        data TEXT NOT NULL DEFAULT '{}',
        logo TEXT,
        signature TEXT,
        is_default INTEGER NOT NULL DEFAULT 0,
        source_share TEXT,
        created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
        updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
      );
;;
CREATE TABLE IF NOT EXISTS invoices (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
        profile_id INTEGER REFERENCES invoice_profiles(id) ON DELETE SET NULL,
        number TEXT NOT NULL,
        status TEXT NOT NULL DEFAULT 'draft',
        issue_date TEXT NOT NULL,
        due_date TEXT,
        currency TEXT NOT NULL,
        client_name TEXT NOT NULL DEFAULT '',
        client_details TEXT NOT NULL DEFAULT '',
        items TEXT NOT NULL DEFAULT '[]',
        tax_rate REAL,
        tax_label TEXT,
        tax_sub TEXT,
        tax_text TEXT,
        subtotal_cents INTEGER NOT NULL DEFAULT 0,
        tax_cents INTEGER NOT NULL DEFAULT 0,
        total_cents INTEGER NOT NULL DEFAULT 0,
        terms TEXT,
        notes TEXT,
        snapshot TEXT NOT NULL DEFAULT '{}',
        sent_at DATETIME,
        paid_at DATETIME,
        created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
        updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
      );
;;
CREATE TABLE IF NOT EXISTS invoice_template_shares (
        code TEXT PRIMARY KEY,
        created_by INTEGER REFERENCES users(id) ON DELETE CASCADE,
        profile_id INTEGER,
        name TEXT NOT NULL,
        layout TEXT NOT NULL,
        currency TEXT NOT NULL,
        number_format TEXT NOT NULL,
        due_days INTEGER NOT NULL,
        data TEXT NOT NULL,
        logo TEXT,
        signature TEXT,
        uses INTEGER NOT NULL DEFAULT 0,
        created_at DATETIME DEFAULT CURRENT_TIMESTAMP
      );
;;
CREATE TABLE IF NOT EXISTS oauth_clients (
        client_id TEXT PRIMARY KEY,
        client_secret_hash TEXT,
        client_name TEXT NOT NULL DEFAULT '',
        redirect_uris TEXT NOT NULL DEFAULT '[]',
        token_endpoint_auth_method TEXT NOT NULL DEFAULT 'none',
        created_at DATETIME DEFAULT CURRENT_TIMESTAMP
      );
;;
CREATE TABLE IF NOT EXISTS oauth_codes (
        code_hash TEXT PRIMARY KEY,
        client_id TEXT NOT NULL,
        user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
        redirect_uri TEXT NOT NULL,
        code_challenge TEXT NOT NULL,
        scope TEXT NOT NULL DEFAULT '',
        resource TEXT,
        expires_at INTEGER NOT NULL,
        created_at DATETIME DEFAULT CURRENT_TIMESTAMP
      );
;;
CREATE TABLE IF NOT EXISTS oauth_tokens (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        token_hash TEXT NOT NULL,
        kind TEXT NOT NULL,
        client_id TEXT NOT NULL,
        user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
        scope TEXT NOT NULL DEFAULT '',
        resource TEXT,
        tv INTEGER NOT NULL DEFAULT 0,
        family TEXT NOT NULL,
        expires_at INTEGER NOT NULL,
        last_used_at DATETIME,
        created_at DATETIME DEFAULT CURRENT_TIMESTAMP
      );
;;
CREATE TABLE IF NOT EXISTS invoice_payments (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        invoice_id INTEGER NOT NULL REFERENCES invoices(id) ON DELETE CASCADE,
        user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
        amount_cents INTEGER NOT NULL,
        paid_on TEXT NOT NULL,
        method TEXT NOT NULL DEFAULT '',
        note TEXT NOT NULL DEFAULT '',
        created_at DATETIME DEFAULT CURRENT_TIMESTAMP
      );
;;
CREATE TABLE IF NOT EXISTS user_ai_keys (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
        provider TEXT NOT NULL,
        label TEXT NOT NULL DEFAULT '',
        key_enc TEXT NOT NULL,
        key_hint TEXT NOT NULL DEFAULT '',
        model TEXT NOT NULL DEFAULT '',
        base_url TEXT,
        is_default INTEGER NOT NULL DEFAULT 0,
        last_used_at DATETIME,
        last_error TEXT,
        created_at DATETIME DEFAULT CURRENT_TIMESTAMP
      );
;;
CREATE TABLE IF NOT EXISTS ai_agent_threads (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
        key_id INTEGER,
        title TEXT NOT NULL DEFAULT '',
        created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
        updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
      );
;;
CREATE TABLE IF NOT EXISTS ai_agent_messages (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        thread_id INTEGER NOT NULL REFERENCES ai_agent_threads(id) ON DELETE CASCADE,
        user_id INTEGER NOT NULL,
        role TEXT NOT NULL,
        content TEXT NOT NULL,
        created_at DATETIME DEFAULT CURRENT_TIMESTAMP
      );
;;
CREATE TABLE IF NOT EXISTS ai_agent_actions (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        thread_id INTEGER NOT NULL REFERENCES ai_agent_threads(id) ON DELETE CASCADE,
        user_id INTEGER NOT NULL,
        message_id INTEGER NOT NULL,
        seq INTEGER NOT NULL DEFAULT 0,
        call_id TEXT NOT NULL,
        tool TEXT NOT NULL,
        args TEXT NOT NULL DEFAULT '{}',
        status TEXT NOT NULL DEFAULT 'pending',
        result TEXT,
        is_error INTEGER NOT NULL DEFAULT 0,
        created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
        resolved_at DATETIME
      );
;;
CREATE TABLE IF NOT EXISTS user_vaults (
        user_id INTEGER PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
        version INTEGER NOT NULL,
        blob BLOB NOT NULL,
        size INTEGER NOT NULL,
        wrapped_pw TEXT,
        wrapped_rc TEXT,
        created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
        updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
      );
;;
CREATE TABLE IF NOT EXISTS vault_grants (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
        token_hash TEXT NOT NULL UNIQUE,
        wrapped_vk TEXT NOT NULL,
        label TEXT,
        created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
        last_used_at DATETIME,
        revoked_at DATETIME
      );
;;
CREATE TABLE IF NOT EXISTS onboarding_progress (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      user_id INTEGER NOT NULL,
      step TEXT NOT NULL,
      completed_at DATETIME DEFAULT CURRENT_TIMESTAMP,
      UNIQUE(user_id, step)
    );
;;
